import {Component,OnInit,OnDestroy} from '@angular/core';
import {CommonModule} from '@angular/common';import {FormsModule} from '@angular/forms';import {RouterModule,ActivatedRoute} from '@angular/router';import {HttpClient} from '@angular/common/http';import {firstValueFrom,Subscription} from 'rxjs';
import {PlatformLayoutComponent} from '../layout/platform-layout/platform-layout.component';import {ReservationAuthService} from '../services/reservation-auth.service';import {LanguageService} from '../services/language.service';
@Component({selector:'app-asset-documents',standalone:true,imports:[CommonModule,FormsModule,RouterModule,PlatformLayoutComponent],templateUrl:'./asset-documents.component.html',styleUrls:['./asset-documents.component.scss']})
export class AssetDocumentsComponent implements OnInit,OnDestroy{
 exemptionReason='';exemptionExpires='';data:any=null;busy=false;dossierReason='';error='';files:Record<string,File>={};expires:Record<string,string>={};reasons:Record<string,string>={};readChecks:Record<string,boolean>={};private sub?:Subscription;private generation=0;private uid='';
 constructor(private http:HttpClient,private auth:ReservationAuthService,private route:ActivatedRoute,public language:LanguageService){}
 get base(){return '/api/manage/assets/'+['type','id'].map(k=>encodeURIComponent(this.route.snapshot.paramMap.get(k)||'')).join('/')+'/documents';}
 t(k:string){return this.data?.labels?.[k]||({title:'Documents',error:'Impossible de charger le dossier. Réessayez.',back:'Retour'} as any)[k]||k;}
 ngOnInit(){this.sub=this.language.language$.subscribe(()=>void this.refresh());}ngOnDestroy(){this.generation++;this.sub?.unsubscribe();}
 async refresh(){const n=++this.generation;this.error='';try{const uid=(await this.auth.user()).uid;const data=await firstValueFrom(this.http.get<any>(this.base,{headers:await this.auth.headers(),params:{language:this.language.currentLanguage}}));if(n!==this.generation||uid!==(await this.auth.user()).uid)return;this.uid=uid;this.data=data;}catch{if(n===this.generation){this.error=this.t('error');this.data=null;}}}
 select(id:string,event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(file&&file.size<=10485760&&['application/pdf','image/jpeg','image/png'].includes(file.type)){this.files[id]=file;this.error='';}else{delete this.files[id];this.error=this.t('formats');}}
 async run(work:()=>Promise<any>){if(this.busy)return;this.busy=true;this.error='';try{if((await this.auth.user()).uid!==this.uid)throw Error('identity_changed');await work();await this.refresh();}catch(e:any){const message=this.t(e?.error?.error==='document_read_required'?'readFirst':e?.error?.error==='document_dossier_incomplete'?'incomplete':e?.error?.error==='invalid_expiry'?'expiryRequired':e?.error?.error==='private_document_bucket_required'?'storageError':'error');await this.refresh();this.error=message;}finally{this.busy=false;}}
 async exempt(active:boolean){if(!this.data?.canReview||this.exemptionReason.trim().length<10){this.error=this.t('requiredReason');return;}await this.run(async()=>firstValueFrom(this.http.post(this.base+'/admin-exemption',{active,reason:this.exemptionReason,expiresOn:this.exemptionExpires,fingerprint:this.data.summary.fingerprint},{headers:await this.auth.headers()})));}
 async submit(){await this.run(async()=>firstValueFrom(this.http.post(this.base+'/submit',{}, {headers:await this.auth.headers()})));}
 async decision(status:string){if(status==='rejected'&&this.dossierReason.trim().length<10){this.error=this.t('requiredReason');return;}await this.run(async()=>firstValueFrom(this.http.post(this.base+'/decision',{status,reason:this.dossierReason,fingerprint:this.data.summary.fingerprint},{headers:await this.auth.headers()})));}
 async upload(r:any){if(!this.files[r.id])return;await this.run(async()=>{const body=new FormData();body.append('requirementId',r.id);body.append('expiresOn',this.expires[r.id]||'');body.append('file',this.files[r.id]);await firstValueFrom(this.http.post(this.base,body,{headers:await this.auth.headers()}));delete this.files[r.id];});}
 async download(d:any){await this.run(async()=>{const blob=await firstValueFrom(this.http.get(this.base+'/'+d.id+'/download',{headers:await this.auth.headers(),responseType:'blob'}));const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=d.filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}
 async remove(d:any){if(!confirm(this.t('deleteConfirm')))return;await this.run(async()=>firstValueFrom(this.http.delete(this.base+'/'+d.id,{headers:await this.auth.headers(),params:{revision:d.revision}})));}
 async waiver(r:any){if((this.reasons[r.id]||'').trim().length<10){this.error=this.t('requiredReason');return;}await this.run(async()=>firstValueFrom(this.http.post(this.base+'/waivers/'+r.id,{reason:this.reasons[r.id]},{headers:await this.auth.headers()})));}
 async review(kind:string,id:string,d:any,status:string){const reason=this.reasons[kind+id]||'';if(status==='rejected'&&reason.trim().length<10){this.error=this.t('requiredReason');return;}await this.run(async()=>firstValueFrom(this.http.post(this.base+'/'+kind+'/'+id+'/review',{status,reason,readConfirmed:this.readChecks[id]===true,revision:d.revision,expiresOn:this.expires[kind+id]||''},{headers:await this.auth.headers()})));}
}
